// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! The secrets of profiles in the OS keyring (feature `keyring`): `api_key`, `access_token` and
//! `refresh_token`, an entry each (service `<cli name>`, user `<profile>:<field>`), the profile
//! keeping `secrets = "keyring"`. Keychain, Credential Manager, or Secret Service over D-Bus.
use super::{config::Credential, error::CliError};

/// The value of `secrets` in a profile whose secrets are in the keyring.
pub const KEYRING: &str = "keyring";

/// Whether this build can use the OS keyring.
pub const ENABLED: bool = cfg!(feature = "keyring");

fn fields(credential: &mut Credential) -> [(&'static str, &mut Option<String>); 3] {
    [
        ("api_key", &mut credential.api_key),
        ("access_token", &mut credential.access_token),
        ("refresh_token", &mut credential.refresh_token),
    ]
}

/// Whether `credential` keeps its secrets in the keyring.
pub fn sealed(credential: &Credential) -> bool {
    credential.secrets.as_deref() == Some(KEYRING)
}

/// Moves the secrets of `credential` to the keyring and marks it so; entries of the fields it
/// lacks are deleted. On failure the credential is left as it was, and the reason returned.
pub fn store(app: &str, profile: &str, credential: &mut Credential) -> Result<(), String> {
    let mut secrets: Vec<(&str, Option<String>)> = fields(credential)
        .into_iter()
        .map(|(field, value)| (field, value.clone()))
        .collect();
    if secrets.iter().all(|(_, value)| value.is_none()) {
        return Err("no secret to store".into());
    }
    for (field, value) in &mut secrets {
        let user = format!("{profile}:{field}");
        match value.take() {
            Some(secret) => os::set(app, &user, &secret)?,
            None => os::delete(app, &user)?,
        }
    }
    for (_, value) in fields(credential) {
        *value = None;
    }
    credential.secrets = Some(KEYRING.to_owned());
    Ok(())
}

/// Reads back the secrets of a credential [`store`] marked; others are left as they are.
pub fn load(app: &str, profile: &str, credential: &mut Credential) -> Result<(), CliError> {
    if !sealed(credential) {
        return Ok(());
    }
    let again = format!("run `{app} auth login --profile {profile}` again");
    if !ENABLED {
        return Err(CliError::config(format!(
            "profile `{profile}` keeps its secrets in the OS keyring, which this build of {app} \
             cannot read: {again}"
        )));
    }
    let mut found = false;
    for (field, value) in fields(credential) {
        let secret = os::get(app, &format!("{profile}:{field}")).map_err(|error| {
            CliError::config(format!("cannot read the OS keyring: {error}; {again}"))
        })?;
        found |= secret.is_some();
        *value = secret;
    }
    match found {
        true => Ok(()),
        false => Err(CliError::config(format!(
            "the OS keyring has no secret of profile `{profile}`: {again}"
        ))),
    }
}

/// Deletes the entries of `profile`, those of every field.
pub fn delete(app: &str, profile: &str) -> Result<(), String> {
    ["api_key", "access_token", "refresh_token"]
        .iter()
        .try_for_each(|field| os::delete(app, &format!("{profile}:{field}")))
}

#[cfg(feature = "keyring")]
mod os {
    use std::sync::{Arc, OnceLock};

    use keyring_core::{CredentialStore, Entry, Error};

    /// The platform's store, unless one was set before (a test's mock).
    fn ready() -> Result<(), String> {
        static PLATFORM: OnceLock<Result<(), String>> = OnceLock::new();
        if keyring_core::get_default_store().is_some() {
            return Ok(());
        }
        PLATFORM
            .get_or_init(|| {
                let store = platform().map_err(|error| error.to_string())?;
                keyring_core::set_default_store(store);
                Ok(())
            })
            .clone()
    }

    #[cfg(target_os = "macos")]
    fn platform() -> keyring_core::Result<Arc<CredentialStore>> {
        Ok(apple_native_keyring_store::keychain::Store::new()?)
    }

    #[cfg(target_os = "windows")]
    fn platform() -> keyring_core::Result<Arc<CredentialStore>> {
        Ok(windows_native_keyring_store::Store::new()?)
    }

    #[cfg(all(unix, not(target_os = "macos")))]
    fn platform() -> keyring_core::Result<Arc<CredentialStore>> {
        Ok(zbus_secret_service_keyring_store::Store::new()?)
    }

    #[cfg(not(any(unix, windows)))]
    fn platform() -> keyring_core::Result<Arc<CredentialStore>> {
        Err(Error::NotSupportedByStore(
            "no OS keyring on this platform".into(),
        ))
    }

    fn entry(service: &str, user: &str) -> Result<Entry, String> {
        ready()?;
        Entry::new(service, user).map_err(|error| error.to_string())
    }

    pub fn set(service: &str, user: &str, secret: &str) -> Result<(), String> {
        let entry = entry(service, user)?;
        entry
            .set_password(secret)
            .map_err(|error| error.to_string())
    }

    pub fn get(service: &str, user: &str) -> Result<Option<String>, String> {
        match entry(service, user)?.get_password() {
            Ok(secret) => Ok(Some(secret)),
            Err(Error::NoEntry) => Ok(None),
            Err(error) => Err(error.to_string()),
        }
    }

    pub fn delete(service: &str, user: &str) -> Result<(), String> {
        match entry(service, user)?.delete_credential() {
            Ok(()) | Err(Error::NoEntry) => Ok(()),
            Err(error) => Err(error.to_string()),
        }
    }
}

#[cfg(not(feature = "keyring"))]
mod os {
    const DISABLED: &str = "this build has no keyring support";

    pub fn set(_: &str, _: &str, _: &str) -> Result<(), String> {
        Err(DISABLED.into())
    }

    pub fn get(_: &str, _: &str) -> Result<Option<String>, String> {
        Err(DISABLED.into())
    }

    pub fn delete(_: &str, _: &str) -> Result<(), String> {
        Ok(())
    }
}

/// The mock store of `keyring-core`, for tests: in memory, shared by the process.
#[cfg(feature = "keyring")]
pub fn use_mock_store() {
    use std::sync::Once;
    static MOCK: Once = Once::new();
    MOCK.call_once(|| {
        let store = keyring_core::mock::Store::new().expect("the mock store");
        keyring_core::set_default_store(store);
    });
}

#[cfg(all(test, feature = "keyring"))]
mod tests {
    use super::*;

    #[test]
    fn secrets_move_to_the_keyring_and_back() {
        use_mock_store();
        let mut credential = Credential {
            access_token: Some("at".into()),
            refresh_token: Some("rt".into()),
            expires_at: Some(1),
            ..Credential::default()
        };
        let hydrated = credential.clone();
        store("acme-test", "prod", &mut credential).unwrap();
        assert_eq!(credential.access_token, None);
        assert_eq!(credential.secrets.as_deref(), Some(KEYRING));
        assert_eq!(credential.expires_at, Some(1));
        let mut loaded = credential.clone();
        load("acme-test", "prod", &mut loaded).unwrap();
        assert_eq!(
            Credential {
                secrets: None,
                ..loaded
            },
            hydrated
        );

        let mut other = Credential::api_key("sk");
        store("acme-test", "prod", &mut other).unwrap();
        let mut loaded = other.clone();
        load("acme-test", "prod", &mut loaded).unwrap();
        assert_eq!(
            (loaded.api_key.as_deref(), loaded.access_token),
            (Some("sk"), None)
        );

        delete("acme-test", "prod").unwrap();
        let error = load("acme-test", "prod", &mut other.clone()).unwrap_err();
        assert_eq!(
            error.message(),
            "the OS keyring has no secret of profile `prod`: run `acme-test auth login --profile prod` again"
        );
        let mut plain = Credential::api_key("sk_file");
        load("acme-test", "prod", &mut plain).unwrap();
        assert_eq!(plain, Credential::api_key("sk_file"));
    }
}
